'use strict';
let posterIncludeNotes=true;
function needsExtraNote(value){return value.length>135||/[\r\n]/.test(value)}
function posterNote(field){
 const value=posterIncludeNotes?(state.plan[field.key]||'').trim():'';
 const compact=value.replace(/\s+/g,' '),short=needsExtraNote(value)?compact.slice(0,110)+(compact.length>110?'…':''):value;
 return `<div class="poster-field"><h3>${field.label}</h3><div class="poster-value" translate="no" dir="auto">${esc(short)}</div>${needsExtraNote(value)?'<small class="poster-continuation">Full note on following pages</small>':''}${!value?'<div class="writing-lines" aria-hidden="true"></div>':''}</div>`;
}
function posterDocument(){
 const extra=PLAN_FIELDS.filter(f=>posterIncludeNotes&&needsExtraNote((state.plan[f.key]||'').trim()));
 const details=[['buildingName','Building name'],['address','Address'],['managerName','Building contact'],['managerPhone','After-hours phone'],['meetingPoint','Orientation meeting point'],['accessibleExit','Accessible exit information'],['evacuationPlan','Building emergency procedure'],['infrastructure','Building infrastructure'],['verifiedOn','Last verified']].filter(([key])=>config[key]);
 return `<div class="poster-document" id="poster-document"><article class="poster-sheet" aria-label="Printable flood plan"><header class="poster-heading"><div><div class="poster-brand" translate="no">≈ SOUTHBANK READY</div><h1>My flood plan</h1><p>Southbank, Melbourne · Keep it somewhere easy to find.</p></div><div class="poster-wave" aria-hidden="true">≈</div></header><section class="poster-contacts" aria-label="Emergency contacts"><div><strong dir="ltr">000</strong><span>Life-threatening emergency</span></div><div><strong dir="ltr">132 500</strong><span>VICSES flood & storm assistance</span></div><div><strong dir="ltr">1800 226 226</strong><span>VicEmergency information</span></div></section><div class="poster-section-label"><span>MY PEOPLE. MY PLACES. MY NEXT STEPS.</span>${icon('home')}</div><section class="poster-fields">${PLAN_FIELDS.map(posterNote).join('')}</section><section class="poster-kit"><h2>Grab-bag essentials</h2><div>${KIT_ITEMS.filter(i=>i.essential).map(i=>`<div class="poster-kit-item">${icon(i.icon)}<span>${i.name}</span><span class="poster-tick" aria-hidden="true">□</span></div>`).join('')}</div></section><section class="poster-rules"><h2>Never enter floodwater.</h2><p>Follow current official warnings. Leave early when advised and safe.</p><div><p>Move basement valuables early, while it is safe. Stay out once water enters.</p><p>Agree help, accessible exits and equipment backup power in advance. Do not rely on lifts.</p></div></section><footer class="poster-footer"><div><strong>Current warnings</strong><span translate="no" dir="ltr">emergency.vic.gov.au</span></div><p>106 is for TTY emergency calls, not SMS.<br><span translate="no" dir="ltr">accesshub.gov.au</span></p><p>Personal planning worksheet. Confirm building arrangements. This is not a live warning or a guaranteed safe route.</p></footer></article>${extra.length||details.length?`<article class="poster-extra"><div class="poster-brand" translate="no">≈ SOUTHBANK READY</div><h1>Plan details</h1><p>Keep these pages with your plan.</p>${extra.map(f=>`<section class="extra-note"><h2>${f.label}</h2><div translate="no" dir="auto">${esc(state.plan[f.key])}</div></section>`).join('')}${details.length?`<h2>Verified building information</h2><p>Use only details confirmed by the building team. An orientation meeting point is not automatically a flood refuge.</p>${details.map(([key,label])=>`<section class="extra-note"><h3>${label}</h3><div translate="no" dir="auto">${esc(config[key])}</div></section>`).join('')}`:''}</article>`:''}</div>`;
}
function posterPage(){return `<div class="page poster-preview"><div class="poster-toolbar"><a class="back-link" href="#plan">← My plan</a><div class="eyebrow">READY FOR YOUR WALL</div><h1>A plan worth keeping.</h1><p>Print an A4 copy or choose “Save as PDF” in your print window. Long notes continue on extra pages.</p><label class="check-row"><input type="checkbox" id="poster-notes" ${posterIncludeNotes?'checked':''}><span>Include my personal notes</span></label><p class="body-note">Choose what you are comfortable displaying. Untick to print a blank copy.</p><button class="primary" data-action="print-plan">${icon('download')} Print / save as PDF</button><p class="body-note">For a clean print, use A4, 100% scale and turn off browser headers and footers.</p></div><div class="poster-stage">${posterDocument()}</div></div>`}
function printPlan(){if(current.view!=='poster'){location.hash='#poster';return}window.print()}
